import{_ as p,a0 as r,w as l,s as o,ao as c,I as n,x as s,a1 as i,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"17 個 tar 命令實用示例 | LCTT x X-CMD","titleTemplate":false,"description":"17 個 tar 命令實用示例 | LCTT (201609) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"17 個 tar 命令實用示例 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"17 個 tar 命令實用示例 | LCTT (201609) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201609/20160911 17 tar command practical examples in Linux","title":"17 個 tar 命令實用示例","tag":"201609","desc":""},"relativePath":"201609/20160911 17 tar command practical examples in Linux.md","filePath":"[post].md"}'),h={name:"201609/20160911 17 tar command practical examples in Linux.md"};function d(g,a,k,b,u,x){const t=r("Link");return l(),o("div",null,[a[13]||(a[13]=c(`<h1 id="_17-個-tar-命令實用示例" tabindex="-1">17 個 tar 命令實用示例 <a class="header-anchor" href="#_17-個-tar-命令實用示例" aria-label="Permalink to “17 個 tar 命令實用示例”">​</a></h1><p>Tar（Tape ARchive，磁帶歸檔的縮寫，LCTT 譯註：最初設計用於將文件打包到磁帶上，現在我們大都使用它來實現備份某個分區或者某些重要的目錄）是類 Unix 系統中使用最廣泛的命令，用於歸檔多個文件或目錄到單個歸檔文件中，並且歸檔文件可以進一步使用 gzip 或者 bzip2 等技術進行壓縮。換言之，tar 命令也可以用於備份：先是歸檔多個文件和目錄到一個單獨的 tar 文件或歸檔文件，然後在需要之時將 tar 文件中的文件和目錄釋放出來。</p><p>本文將介紹 tar 的 17 個實用示例。</p><p>tar 命令語法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tar &lt;選項&gt; &lt;文件&gt;</span></span></code></pre></div><p>下面列舉 tar 命令中一些常用的選項：</p><blockquote><p>--delete : 從歸檔文件 (而非磁帶) 中刪除</p></blockquote><blockquote><p>-r, --append : 將文件追加到歸檔文件中</p></blockquote><blockquote><p>-t, --list : 列出歸檔文件中包含的內容</p></blockquote><blockquote><p>--test-label : 測試歸檔文件卷標並退出</p></blockquote><blockquote><p>-u, --update : 將已更新的文件追加到歸檔文件中</p></blockquote><blockquote><p>-x, --extract, --get : 釋放歸檔文件中文件及目錄</p></blockquote><blockquote><p>-C, --directory=DIR : 執行歸檔動作前變更工作目錄到 DIR</p></blockquote><blockquote><p>-f, --file=ARCHIVE : 指定 (將要創建或已存在的) 歸檔文件名</p></blockquote><blockquote><p>-j, --bip2 : 對歸檔文件使用 bzip2 壓縮</p></blockquote><blockquote><p>-J, --xz : 對歸檔文件使用 xz 壓縮</p></blockquote><blockquote><p>-p, --preserve-permissions : 保留原文件的訪問權限</p></blockquote><blockquote><p>-v, --verbose : 顯示命令整個執行過程</p></blockquote><blockquote><p>-z, gzip : 對歸檔文件使用 gzip 壓縮</p></blockquote><p>注 : 在 tar 命令選項中的連接符 <code>-</code> 是可選的（LCTT 譯註：不用 <code>-</code> 也沒事。這在 GNU 軟件裏面很罕見，大概是由於 tar 命令更多受到古老的 UNIX 風格影響）。</p><h3 id="示例-1-創建一個-tar-歸檔文件" tabindex="-1">示例 1：創建一個 tar 歸檔文件 <a class="header-anchor" href="#示例-1-創建一個-tar-歸檔文件" aria-label="Permalink to “示例 1：創建一個 tar 歸檔文件”">​</a></h3><p>現在來創建一個 tar 文件，將 /etc/ 目錄和 /root/anaconda-ks.cfg 文件打包進去。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -cvf myarchive.tar /etc /root/anaconda-ks.cfg</span></span></code></pre></div><p>以上命令會在當前目錄創建一個名為 &quot;myarchive&quot; 的 tar 文件，內含 /etc/ 目錄和 /root/anaconda-ks.cfg 文件。</p><p>其中，<code>-c</code> 選項表示要創建 tar 文件，<code>-v</code> 選項用於輸出 tar 的詳細過程到屏幕上，<code>-f</code> 選項則是指定歸檔文件名稱。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# ls -l myarchive.tar</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 22947840 Sep 7 00:24 myarchive.tar</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><h3 id="示例-2-列出歸檔文件中的內容" tabindex="-1">示例 2：列出歸檔文件中的內容 <a class="header-anchor" href="#示例-2-列出歸檔文件中的內容" aria-label="Permalink to “示例 2：列出歸檔文件中的內容”">​</a></h3><p>在 tar 命令中使用 <code>–t</code> 選項可以不用釋放其中的文件就可以快速列出文件中包含的內容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -tvf myarchive.tar</span></span></code></pre></div><p>列出 tar 文件中的指定的文件和目錄。下列命令嘗試查看 anaconda-ks.cfg 文件是否存在於 tar 文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -tvf myarchive.tar root/anaconda-ks.cfg</span></span>
<span class="line"><span>-rw------- root/root 953 2016-08-24 01:33 root/anaconda-ks.cfg</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><h3 id="示例-3-追加文件到歸檔-tar-文件中" tabindex="-1">示例 3：追加文件到歸檔（tar）文件中 <a class="header-anchor" href="#示例-3-追加文件到歸檔-tar-文件中" aria-label="Permalink to “示例 3：追加文件到歸檔（tar）文件中”">​</a></h3><p><code>-r</code> 選項用於向已有的 tar 文件中追加文件。下面來將 /etc/fstab 添加到 data.tar 中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -rvf data.tar /etc/fstab</span></span></code></pre></div><p>注：在壓縮過的 tar 文件中無法進行追加文件操作。</p><h3 id="示例-4-從-tar-文件中釋放文件以及目錄" tabindex="-1">示例 4：從 tar 文件中釋放文件以及目錄 <a class="header-anchor" href="#示例-4-從-tar-文件中釋放文件以及目錄" aria-label="Permalink to “示例 4：從 tar 文件中釋放文件以及目錄”">​</a></h3><p><code>-x</code> 選項用於釋放出 tar 文件中的文件和目錄。下面來釋放上邊創建的 tar 文件中的內容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -xvf myarchive.tar</span></span></code></pre></div><p>這個命令會在當前目錄中釋放出 myarchive.tar 文件中的內容。</p><h3 id="示例-5-釋放-tar-文件到指定目錄" tabindex="-1">示例 5：釋放 tar 文件到指定目錄 <a class="header-anchor" href="#示例-5-釋放-tar-文件到指定目錄" aria-label="Permalink to “示例 5：釋放 tar 文件到指定目錄”">​</a></h3><p>假如你想要釋放 tar 文件中的內容到指定的文件夾或者目錄，使用 <code>-C</code> 選項後邊加上指定的文件的路徑。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -xvf myarchive.tar -C /tmp/</span></span></code></pre></div><h3 id="示例-6-釋放-tar-文件中的指定文件或目錄" tabindex="-1">示例 6：釋放 tar 文件中的指定文件或目錄 <a class="header-anchor" href="#示例-6-釋放-tar-文件中的指定文件或目錄" aria-label="Permalink to “示例 6：釋放 tar 文件中的指定文件或目錄”">​</a></h3><p>假設你只要釋放 tar 文件中的 anaconda-ks.cfg 到 /tmp 目錄。</p><p>語法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tar –xvf {tar-file } {file-to-be-extracted } -C {path-where-to-extract}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[root@linuxtechi tmp]# tar -xvf /root/myarchive.tar root/anaconda-ks.cfg -C /tmp/</span></span>
<span class="line"><span>root/anaconda-ks.cfg</span></span>
<span class="line"><span>[root@linuxtechi tmp]# ls -l /tmp/root/anaconda-ks.cfg</span></span>
<span class="line"><span>-rw-------. 1 root root 953 Aug 24 01:33 /tmp/root/anaconda-ks.cfg</span></span>
<span class="line"><span>[root@linuxtechi tmp]#</span></span></code></pre></div><h3 id="示例-7-創建並壓縮歸檔文件-tar-gz-或-tgz" tabindex="-1">示例 7：創建並壓縮歸檔文件（.tar.gz 或 .tgz） <a class="header-anchor" href="#示例-7-創建並壓縮歸檔文件-tar-gz-或-tgz" aria-label="Permalink to “示例 7：創建並壓縮歸檔文件（.tar.gz 或 .tgz）”">​</a></h3><p>假設我們需要打包 /etc 和 /opt 文件夾，並用 gzip 工具將其壓縮。可以在 tar 命令中使用 <code>-z</code> 選項來實現。這種 tar 文件的擴展名可以是 .tar.gz 或者 .tgz。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -zcpvf myarchive.tar.gz /etc/ /opt/</span></span></code></pre></div><p>或</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -zcpvf myarchive.tgz /etc/ /opt/</span></span></code></pre></div><h3 id="示例-8-創建並壓縮歸檔文件-tar-bz2-或-tbz2" tabindex="-1">示例 8：創建並壓縮歸檔文件（.tar.bz2 或 .tbz2） <a class="header-anchor" href="#示例-8-創建並壓縮歸檔文件-tar-bz2-或-tbz2" aria-label="Permalink to “示例 8：創建並壓縮歸檔文件（.tar.bz2 或 .tbz2）”">​</a></h3><p>假設我們需要打包 /etc 和 /opt 文件夾，並使用 bzip2 壓縮。可以在 tar 命令中使用 <code>-j</code> 選項來實現。這種 tar 文件的擴展名可以是 .tar.bz2 或者 .tbz。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -jcpvf myarchive.tar.bz2 /etc/ /opt/</span></span></code></pre></div><p>或</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -jcpvf myarchive.tbz2 /etc/ /opt/</span></span></code></pre></div><h3 id="示例-9-排除指定文件或類型後創建-tar-文件" tabindex="-1">示例 9：排除指定文件或類型後創建 tar 文件 <a class="header-anchor" href="#示例-9-排除指定文件或類型後創建-tar-文件" aria-label="Permalink to “示例 9：排除指定文件或類型後創建 tar 文件”">​</a></h3><p>創建 tar 文件時在 tar 命令中使用 <code>–exclude</code> 選項來排除指定文件或者類型。假設在創建壓縮的 tar 文件時要排除 .html 文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -zcpvf myarchive.tgz /etc/ /opt/ --exclude=*.html</span></span></code></pre></div><h3 id="示例-10-列出-tar-gz-或-tgz-文件中的內容" tabindex="-1">示例 10：列出 .tar.gz 或 .tgz 文件中的內容 <a class="header-anchor" href="#示例-10-列出-tar-gz-或-tgz-文件中的內容" aria-label="Permalink to “示例 10：列出 .tar.gz 或 .tgz 文件中的內容”">​</a></h3><p>使用 <code>-t</code> 選項可以查看 .tar.gz 或 .tgz 文件中內容。如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -tvf myarchive.tgz  | more</span></span>
<span class="line"><span>.............................................</span></span>
<span class="line"><span>drwxr-xr-x root/root         0 2016-09-07 08:41 etc/</span></span>
<span class="line"><span>-rw-r--r-- root/root       541 2016-08-24 01:23 etc/fstab</span></span>
<span class="line"><span>-rw------- root/root         0 2016-08-24 01:23 etc/crypttab</span></span>
<span class="line"><span>lrwxrwxrwx root/root         0 2016-08-24 01:23 etc/mtab -&gt; /proc/self/mounts</span></span>
<span class="line"><span>-rw-r--r-- root/root       149 2016-09-07 08:41 etc/resolv.conf</span></span>
<span class="line"><span>drwxr-xr-x root/root         0 2016-09-06 03:55 etc/pki/</span></span>
<span class="line"><span>drwxr-xr-x root/root         0 2016-09-06 03:15 etc/pki/rpm-gpg/</span></span>
<span class="line"><span>-rw-r--r-- root/root      1690 2015-12-09 04:59 etc/pki/rpm-gpg/RPM-GPG-KEY-CentOS-7</span></span>
<span class="line"><span>-rw-r--r-- root/root      1004 2015-12-09 04:59 etc/pki/rpm-gpg/RPM-GPG-KEY-CentOS-Debug-7</span></span>
<span class="line"><span>-rw-r--r-- root/root      1690 2015-12-09 04:59 etc/pki/rpm-gpg/RPM-GPG-KEY-CentOS-Testing-7</span></span>
<span class="line"><span>-rw-r--r-- root/root      3140 2015-09-15 06:53 etc/pki/rpm-gpg/RPM-GPG-KEY-foreman</span></span>
<span class="line"><span>..........................................................</span></span></code></pre></div><h3 id="示例-11-列出-tar-bz2-或-tbz2-文件中的內容" tabindex="-1">示例 11：列出 .tar.bz2 或 .tbz2 文件中的內容 <a class="header-anchor" href="#示例-11-列出-tar-bz2-或-tbz2-文件中的內容" aria-label="Permalink to “示例 11：列出 .tar.bz2 或 .tbz2 文件中的內容”">​</a></h3><p>使用 <code>-t</code> 選項可以查看 .tar.bz2 或 .tbz2 文件中內容。如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -tvf myarchive.tbz2  | more</span></span>
<span class="line"><span>........................................................</span></span>
<span class="line"><span>rwxr-xr-x root/root         0 2016-08-24 01:25 etc/pki/java/</span></span>
<span class="line"><span>lrwxrwxrwx root/root         0 2016-08-24 01:25 etc/pki/java/cacerts -&gt; /etc/pki/ca-trust/extracted/java/cacerts</span></span>
<span class="line"><span>drwxr-xr-x root/root         0 2016-09-06 02:54 etc/pki/nssdb/</span></span>
<span class="line"><span>-rw-r--r-- root/root     65536 2010-01-12 15:09 etc/pki/nssdb/cert8.db</span></span>
<span class="line"><span>-rw-r--r-- root/root      9216 2016-09-06 02:54 etc/pki/nssdb/cert9.db</span></span>
<span class="line"><span>-rw-r--r-- root/root     16384 2010-01-12 16:21 etc/pki/nssdb/key3.db</span></span>
<span class="line"><span>-rw-r--r-- root/root     11264 2016-09-06 02:54 etc/pki/nssdb/key4.db</span></span>
<span class="line"><span>-rw-r--r-- root/root       451 2015-10-21 09:42 etc/pki/nssdb/pkcs11.txt</span></span>
<span class="line"><span>-rw-r--r-- root/root     16384 2010-01-12 15:45 etc/pki/nssdb/secmod.db</span></span>
<span class="line"><span>drwxr-xr-x root/root         0 2016-08-24 01:26 etc/pki/CA/</span></span>
<span class="line"><span>drwxr-xr-x root/root         0 2015-06-29 08:48 etc/pki/CA/certs/</span></span>
<span class="line"><span>drwxr-xr-x root/root         0 2015-06-29 08:48 etc/pki/CA/crl/</span></span>
<span class="line"><span>drwxr-xr-x root/root         0 2015-06-29 08:48 etc/pki/CA/newcerts/</span></span>
<span class="line"><span>drwx------ root/root         0 2015-06-29 08:48 etc/pki/CA/private/</span></span>
<span class="line"><span>drwx------ root/root         0 2015-11-20 06:34 etc/pki/rsyslog/</span></span>
<span class="line"><span>drwxr-xr-x root/root         0 2016-09-06 03:44 etc/pki/pulp/</span></span>
<span class="line"><span>..............................................................</span></span></code></pre></div><h3 id="示例-12-解壓-tar-gz-或-tgz-文件" tabindex="-1">示例 12：解壓 .tar.gz 或 .tgz 文件 <a class="header-anchor" href="#示例-12-解壓-tar-gz-或-tgz-文件" aria-label="Permalink to “示例 12：解壓 .tar.gz 或 .tgz 文件”">​</a></h3><p>使用 <code>-x</code> 和 <code>-z</code> 選項來解壓 .tar.gz 或 .tgz 文件。如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -zxpvf myarchive.tgz -C /tmp/</span></span></code></pre></div><p>以上命令將 tar 文件解壓到 /tmp 目錄。</p><p>注：現今的 tar 命令會在執行解壓動作前自動檢查文件的壓縮類型，這意味着我們在使用 tar 命令是可以不用指定文件的壓縮類型。如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -xpvf myarchive.tgz -C /tmp/</span></span></code></pre></div><h3 id="示例-13-解壓-tar-bz2-或-tbz2-文件" tabindex="-1">示例 13：解壓 .tar.bz2 或 .tbz2 文件 <a class="header-anchor" href="#示例-13-解壓-tar-bz2-或-tbz2-文件" aria-label="Permalink to “示例 13：解壓 .tar.bz2 或 .tbz2 文件”">​</a></h3><p>使用 <code>-j</code> 和 <code>-x</code> 選項來解壓 .tar.bz2 或 .tbz2 文件。如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -jxpvf myarchive.tbz2 -C /tmp/</span></span></code></pre></div><p>或</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar xpvf myarchive.tbz2 -C /tmp/</span></span></code></pre></div><h3 id="示例-14-使用-tar-命令進行定時備份" tabindex="-1">示例 14：使用 tar 命令進行定時備份 <a class="header-anchor" href="#示例-14-使用-tar-命令進行定時備份" aria-label="Permalink to “示例 14：使用 tar 命令進行定時備份”">​</a></h3><p>總有一些實時場景需要我們對指定的文件和目錄進行打包，已達到日常備份的目的。假設需要每天備份整個 /opt 目錄，可以創建一個帶 tar 命令的 cron 任務來完成。如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -zcvf optbackup-$(date +%Y-%m-%d).tgz /opt/</span></span></code></pre></div><p>為以上命令創建一個 cron 任務即可。</p><h3 id="示例-15-使用-t-及-x-創建壓縮歸檔文件" tabindex="-1">示例 15：使用 -T 及 -X 創建壓縮歸檔文件 <a class="header-anchor" href="#示例-15-使用-t-及-x-創建壓縮歸檔文件" aria-label="Permalink to “示例 15：使用 -T 及 -X 創建壓縮歸檔文件”">​</a></h3><p>想像這樣一個場景：把想要歸檔和壓縮的文件及目錄記錄到到一個文件，然後把這個文件當做 tar 命令的傳入參數來完成歸檔任務；而有時候則是需要排除上面提到的這個文件裏面記錄的特定路徑後進行歸檔和壓縮。</p><p>在 tar 命令中使用 <code>-T</code> 選項來指定該輸入文件，使用 <code>-X</code> 選項來指定包含要排除的文件列表。</p><p>假設要歸檔 /etc、/opt、/home 目錄，並排除 /etc/sysconfig/kdump 和 /etc/sysconfig/foreman 文件，可以創建 /root/tar-include 和 /root/tar-exclude 然後分別輸入以下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# cat /root/tar-include</span></span>
<span class="line"><span>/etc</span></span>
<span class="line"><span>/opt</span></span>
<span class="line"><span>/home</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span>
<span class="line"><span>[root@linuxtechi ~]# cat /root/tar-exclude</span></span>
<span class="line"><span>/etc/sysconfig/kdump</span></span>
<span class="line"><span>/etc/sysconfig/foreman</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>運行以下命令來創建一個壓縮歸檔文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar zcpvf mybackup-$(date +%Y-%m-%d).tgz -T /root/tar-include -X /root/tar-exclude</span></span></code></pre></div><h3 id="示例-16-查看-tar、-tgz-和-tbz2-文件的大小" tabindex="-1">示例 16：查看 .tar、.tgz 和 .tbz2 文件的大小 <a class="header-anchor" href="#示例-16-查看-tar、-tgz-和-tbz2-文件的大小" aria-label="Permalink to “示例 16：查看 .tar、.tgz 和 .tbz2 文件的大小”">​</a></h3><p>使用如下命令來查看 (壓縮) tar 文件的體積。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -czf - data.tar | wc -c</span></span>
<span class="line"><span>427</span></span>
<span class="line"><span>[root@linuxtechi ~]# tar -czf - mybackup-2016-09-09.tgz | wc -c</span></span>
<span class="line"><span>37956009</span></span>
<span class="line"><span>[root@linuxtechi ~]# tar -czf - myarchive.tbz2 | wc -c</span></span>
<span class="line"><span>30835317</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><h3 id="示例-17-分割體積龐大的-tar-文件為多份小文件" tabindex="-1">示例 17：分割體積龐大的 tar 文件為多份小文件 <a class="header-anchor" href="#示例-17-分割體積龐大的-tar-文件為多份小文件" aria-label="Permalink to “示例 17：分割體積龐大的 tar 文件為多份小文件”">​</a></h3><p>類 Unix 系統中使用 split 命令來將大體積文件分割成小體積文件。大體積的 tar 當然也可以使用這個命令來進行分割。</p><p>假設需要將 &quot;mybackup-2016-09-09.tgz&quot; 分割成每份 6 MB 的小文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Syntax :  split -b &lt;Size-in-MB&gt; &lt;tar-file-name&gt;.&lt;extension&gt; “prefix-name”</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# split -b 6M mybackup-2016-09-09.tgz mybackup-parts</span></span></code></pre></div><p>以上命令會在當前目錄分割 mybackup-2016-09-09.tgz 文件成為多個 6 MB 的小文件，文件名為 mybackup-partsaa ~ mybackup-partsag。如果在要在分割文件後以數字而非字母來區分，可以在以上的 split 命令使用 <code>-d</code> 選項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# ls -l mybackup-parts*</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 6291456 Sep 10 03:05 mybackup-partsaa</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 6291456 Sep 10 03:05 mybackup-partsab</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 6291456 Sep 10 03:05 mybackup-partsac</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 6291456 Sep 10 03:05 mybackup-partsad</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 6291456 Sep 10 03:05 mybackup-partsae</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 6291456 Sep 10 03:05 mybackup-partsaf</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 637219  Sep 10 03:05 mybackup-partsag</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>然後通過網絡將這些分割文件轉移到其他服務器，就可以合併成為一個單獨的 tar 文件了，如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# cat mybackup-partsa* &gt; mybackup-2016-09-09.tgz</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>文畢，希望你喜歡 tar 命令的這幾個不同的示例。隨時評論並分享你的心得。</p><hr>`,101)),n("p",null,[a[1]||(a[1]=s("via: ",-1)),i(t,{href:"http://www.linuxtechi.com/17-tar-command-examples-in-linux/"},{default:e(()=>[...a[0]||(a[0]=[s("http://www.linuxtechi.com/17-tar-command-examples-in-linux/",-1)])]),_:1})]),n("p",null,[a[5]||(a[5]=s("作者：",-1)),i(t,{href:"http://www.linuxtechi.com/author/pradeep/"},{default:e(()=>[...a[2]||(a[2]=[s("Pradeep Kumar",-1)])]),_:1}),a[6]||(a[6]=s(" 譯者：",-1)),i(t,{href:"https://github.com/GHLandy"},{default:e(()=>[...a[3]||(a[3]=[s("GHLandy",-1)])]),_:1}),a[7]||(a[7]=s(" 校對：",-1)),i(t,{href:"https://github.com/wxy"},{default:e(()=>[...a[4]||(a[4]=[s("wxy",-1)])]),_:1})]),n("p",null,[a[10]||(a[10]=s("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...a[8]||(a[8]=[s("LCTT",-1)])]),_:1}),a[11]||(a[11]=s(" 原創編譯，",-1)),i(t,{href:"https://linux.cn/"},{default:e(()=>[...a[9]||(a[9]=[s("Linux中國",-1)])]),_:1}),a[12]||(a[12]=s(" 榮譽推出",-1))])])}const v=p(h,[["render",d]]);export{y as __pageData,v as default};
